<script lang="ts">
  import { createEventDispatcher } from "svelte";
  import { ulid } from "ulid";
  import { push } from "svelte-spa-router";
  import type {
    ApprovalType,
    CreateQuestionRequest,
    EditQuestionRequest,
    Question,
    ResponseOption,
    UserSession,
  } from "../lib/types";
  import { api, ApiError } from "../lib/api";
  import {
    TITLE_MAX_LENGTH,
    TARGET_AUDIENCE_MAX_LENGTH,
    DESCRIPTION_MAX_LENGTH,
  } from "../lib/limits";
  import { invalidateQuestion, pushToast } from "../lib/stores";
  import { isoToLocalInput, localInputToIso, secondsRemaining } from "../lib/time";
  import { audienceFor, ensureProjectNames, isKnownProject } from "../lib/projects";
  import ProjectPicker from "./ProjectPicker.svelte";
  import ApprovalTypeSelector from "./ApprovalTypeSelector.svelte";
  import ResponseOptionEditor from "./ResponseOptionEditor.svelte";
  import ErrorAlert from "./ErrorAlert.svelte";

  export let mode: "create" | "edit";
  export let user: UserSession;
  export let question: Question | null = null;

  const dispatch = createEventDispatcher<{ saved: Question }>();

  // Editing a question whose deadline already elapsed is the supported
  // way to reopen it: the backend only refuses edits once `status` leaves
  // "open", so a later `closes_at` puts the question back in front of its
  // voters. The field's help text says so, rather than leaving the
  // requester to guess whether a passed deadline is final.
  $: deadlineHasPassed =
    question != null && secondsRemaining(question.closes_at) <= 0;

  function defaultClosesLocal(): string {
    const d = new Date(Date.now() + 7 * 86400 * 1000);
    return isoToLocalInput(d.toISOString());
  }

  function defaultResponseOption(at: ApprovalType): ResponseOption {
    if (at === "lazy_consensus")
      return { kind: "lazy_consensus", allow_comment: true };
    return {
      kind: "vote",
      allowed_values: ["+1", "+0", "-0", "-1"],
      allow_comment: true,
    };
  }

  let title = question?.title ?? "";
  let description = question?.description ?? "";
  let projectId =
    question?.project_id ?? (user.projects.length > 0 ? user.projects[0] : "");
  let targetAudience = question?.target_audience ?? audienceFor(projectId);

  // Keep the target audience in step with the selected project, but only
  // while it still holds the auto-generated default — once the user edits
  // it by hand we leave it alone (issue #14). Edit mode pins the project,
  // so this only matters when creating.
  let autoAudience = audienceFor(projectId);
  let lastProject = projectId;
  $: if (projectId !== lastProject) {
    const next = audienceFor(projectId);
    if (mode === "create" && targetAudience === autoAudience) {
      targetAudience = next;
    }
    autoAudience = next;
    lastProject = projectId;
    // If the canonical name isn't bundled (e.g. a brand-new project),
    // fetch the live feed once and re-apply if still on the default.
    if (mode === "create" && projectId && !isKnownProject(projectId)) {
      const pending = projectId;
      ensureProjectNames().then(() => {
        if (pending !== projectId) return;
        const refreshed = audienceFor(projectId);
        if (refreshed === autoAudience) return;
        if (targetAudience === autoAudience) targetAudience = refreshed;
        autoAudience = refreshed;
      });
    }
  }
  let approvalType: ApprovalType =
    question?.approval_type ?? "majority_approval";
  // The switch is a boolean view of the question's `binding_scope`: off
  // (the default) is committee-only binding votes, on extends them to every
  // project member. Not editable after filing, like `approval_type`.
  let projectBinding: boolean =
    (question?.binding_scope ?? "committee") === "project";
  let isPrivate: boolean = question?.is_private ?? false;
  let responseOption: ResponseOption =
    question?.response_option ?? defaultResponseOption(approvalType);
  let closesLocal =
    question != null ? isoToLocalInput(question.closes_at) : defaultClosesLocal();
  let requestId = question?.request_id ?? "";

  // When creating, the privacy checkbox is only enabled if the selected
  // project is in session.committees.
  $: canMarkPrivate =
    mode === "edit" ? true : user.committees.includes(projectId);
  $: if (!canMarkPrivate) isPrivate = isPrivate && false;

  let submitting = false;
  let errorMsg: string | null = null;

  function validate(): string | null {
    if (!title.trim()) return "Title is required.";
    if (title.length > TITLE_MAX_LENGTH)
      return `Title must be ${TITLE_MAX_LENGTH.toLocaleString()} characters or fewer.`;
    if (!description.trim()) return "Description is required.";
    if (description.length > DESCRIPTION_MAX_LENGTH)
      return `Description must be ${DESCRIPTION_MAX_LENGTH.toLocaleString()} characters or fewer.`;
    if (!projectId) return "Choose a project.";
    if (!targetAudience.trim()) return "Target audience is required.";
    if (targetAudience.length > TARGET_AUDIENCE_MAX_LENGTH)
      return `Target audience must be ${TARGET_AUDIENCE_MAX_LENGTH.toLocaleString()} characters or fewer.`;
    if (!closesLocal) return "Set a deadline.";
    const closesIso = localInputToIso(closesLocal);
    if (mode === "create" && Date.parse(closesIso) <= Date.now())
      return "Deadline must be in the future.";
    return null;
  }

  async function onSubmit() {
    errorMsg = validate();
    if (errorMsg) return;
    submitting = true;
    try {
      if (mode === "create") {
        const body: CreateQuestionRequest = {
          project_id: projectId,
          title: title.trim(),
          description: description.trim(),
          target_audience: targetAudience.trim(),
          approval_type: approvalType,
          binding_scope: projectBinding ? "project" : "committee",
          is_private: isPrivate,
          response_option: responseOption,
          closes_at: localInputToIso(closesLocal),
        };
        const created = await api.createQuestion(body);
        pushToast("success", `Question #${created.question_id} filed.`);
        dispatch("saved", created);
        push(`/question/${created.question_id}`);
      } else if (question) {
        const patch: EditQuestionRequest = {};
        if (title !== question.title) patch.title = title.trim();
        if (description !== question.description)
          patch.description = description.trim();
        if (targetAudience !== question.target_audience)
          patch.target_audience = targetAudience.trim();
        if (isPrivate !== question.is_private) patch.is_private = isPrivate;
        const closesIso = localInputToIso(closesLocal);
        if (closesIso !== question.closes_at) patch.closes_at = closesIso;
        if (
          JSON.stringify(responseOption) !==
          JSON.stringify(question.response_option)
        )
          patch.response_option = responseOption;

        const updated = await api.editQuestion(question.question_id, patch);
        invalidateQuestion(question.question_id);
        pushToast("success", `Question #${updated.question_id} updated.`);
        dispatch("saved", updated);
        push(`/question/${updated.question_id}`);
      }
    } catch (err) {
      if (err instanceof ApiError) {
        errorMsg =
          err.body?.message ||
          err.body?.error ||
          `Request failed with status ${err.status}.`;
      } else {
        errorMsg = err instanceof Error ? err.message : "Submission failed.";
      }
    } finally {
      submitting = false;
    }
  }

  function onCancel() {
    if (mode === "edit" && question) {
      push(`/question/${question.question_id}`);
    } else {
      push("/");
    }
  }

  const editReadonly = mode === "edit";
</script>

<form class="card" on:submit|preventDefault={onSubmit}>
  <div class="card-body">
    {#if errorMsg}
      <ErrorAlert title="Could not save" message={errorMsg} />
    {/if}

    <div class="row g-3">
      <div class="col-12">
        <label class="form-label" for="q-title">Title</label>
        <input
          id="q-title"
          class="form-control"
          type="text"
          maxlength={TITLE_MAX_LENGTH}
          bind:value={title}
          required
        />
        <div class="form-text">
          {title.length.toLocaleString()} / {TITLE_MAX_LENGTH.toLocaleString()}
        </div>
      </div>

      <div class="col-12">
        <label class="form-label" for="q-desc">Description</label>
        <textarea
          id="q-desc"
          class="form-control"
          rows="6"
          maxlength={DESCRIPTION_MAX_LENGTH}
          bind:value={description}
          required
        ></textarea>
        <div class="form-text">
          {description.length.toLocaleString()} / {DESCRIPTION_MAX_LENGTH.toLocaleString()}
        </div>
      </div>

      <div class="col-md-6">
        <label class="form-label" for="q-project">Project</label>
        <ProjectPicker
          id="q-project"
          bind:value={projectId}
          options={user.projects}
          disabled={editReadonly}
        />
        {#if editReadonly}
          <div class="form-text">Cannot be changed once the question is filed.</div>
        {/if}
      </div>

      <div class="col-md-6">
        <label class="form-label" for="q-audience">Target audience</label>
        <input
          id="q-audience"
          class="form-control"
          type="text"
          maxlength={TARGET_AUDIENCE_MAX_LENGTH}
          bind:value={targetAudience}
          required
        />
        <div class="form-text">
          This is a description of the intended audience for this vote, so
          that respondents can understand the context of the question.
        </div>
        <div class="form-text">
          {targetAudience.length.toLocaleString()} / {TARGET_AUDIENCE_MAX_LENGTH.toLocaleString()}
        </div>
      </div>

      <div class="col-md-6">
        <label class="form-label" for="q-closes">Closes at (local time)</label>
        <input
          id="q-closes"
          class="form-control"
          type="datetime-local"
          bind:value={closesLocal}
          required
        />
        <div class="form-text">
          Sent to the server as UTC. Voters see a local-time countdown.
          {#if mode === "create"}
            You are not locked into this date: while the question is
            unresolved you can edit it and move the deadline out, which
            reopens voting even if the original date has already passed.
          {:else if deadlineHasPassed}
            Voting closed at this deadline. Moving it into the future
            reopens the question for responses; every response already
            recorded is kept.
          {:else}
            Moving this out extends the voting window; moving it in
            closes the question sooner.
          {/if}
        </div>
      </div>

      <div class="col-md-6 d-flex flex-column">
        <div class="form-label">Flags</div>
        <div class="form-check form-switch">
          <input
            id="q-binding"
            class="form-check-input"
            type="checkbox"
            bind:checked={projectBinding}
            disabled={editReadonly}
            aria-describedby="q-binding-help"
          />
          <label for="q-binding" class="form-check-label"
            >Committers cast binding votes</label
          >
        </div>
        <div class="form-text" id="q-binding-help">
          {#if projectBinding}
            Every committer on the project casts a binding vote alongside the
            committee, so their votes count toward the outcome (and can veto a
            unanimous-approval question).
          {:else}
            Only committee (PMC/PPMC) members cast binding votes. Committers
            may still respond, but their votes are recorded without counting
            toward the outcome.
          {/if}
          Only binding votes are tallied when the question resolves; votes from
          outside the project never bind.
          {#if editReadonly}
            Cannot be changed once the question is filed.
          {/if}
        </div>
        <div class="form-check form-switch">
          <input
            id="q-private"
            class="form-check-input"
            type="checkbox"
            bind:checked={isPrivate}
            disabled={!canMarkPrivate}
            aria-describedby={canMarkPrivate ? undefined : "q-private-help"}
          />
          <label for="q-private" class="form-check-label">
            <i class="fa-solid fa-lock me-1"></i>Private (committee only)
          </label>
        </div>
        {#if !canMarkPrivate}
          <div class="form-text" id="q-private-help">
            Only members of <code>{projectId || "(no project)"}</code>'s committee
            may mark a question private.
          </div>
        {/if}
      </div>

      <div class="col-12">
        <div class="form-label">Approval type</div>
        <ApprovalTypeSelector bind:value={approvalType} disabled={editReadonly} />
        {#if editReadonly}
          <div class="form-text">Cannot be changed once the question is filed.</div>
        {/if}
      </div>

      <div class="col-12">
        <div class="form-label">Response options</div>
        <ResponseOptionEditor
          {approvalType}
          bind:value={responseOption}
        />
      </div>
    </div>
  </div>
  <div class="card-footer d-flex justify-content-between bg-white">
    <button type="button" class="btn btn-link" on:click={onCancel}>
      Cancel
    </button>
    <button class="btn btn-primary" type="submit" disabled={submitting}>
      {#if submitting}
        <i class="fa-solid fa-circle-notch fa-spin me-1"></i>
      {/if}
      {mode === "create" ? "File question" : "Save changes"}
    </button>
  </div>
</form>
